CREATE TABLE reporting.saved_erp_reports (
  id uuid PRIMARY KEY,
  owner_account_id uuid NOT NULL REFERENCES identity.user_accounts(id),
  scope varchar(30) NOT NULL CHECK (scope IN ('procurement','warehouse','sales','logistics')),
  name varchar(100) NOT NULL CHECK (length(trim(name)) > 0),
  configuration jsonb NOT NULL CHECK (jsonb_typeof(configuration) = 'object' AND configuration ? 'definitionKey' AND configuration->>'definitionKey' LIKE scope || '.%'),
  request_hash char(64) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX saved_erp_reports_owner_idx ON reporting.saved_erp_reports(owner_account_id,scope,created_at DESC,id);
